-- Positive functional smoke for the shared launch batch.
-- LOCAL integration PostgreSQL 17 only.
-- Reproduces the database payload shape generated by processLancamentosInSequence
-- for one synthetic E1 launch (1 piece). All stock, history, batch and archive
-- writes occur in one transaction and are rolled back before the script exits.

-- Capture the authoritative control state before opening the test transaction.
SELECT
  generation_id::text AS baseline_generation_id,
  revision::text AS baseline_revision
FROM public.lancamento_draft_control
WHERE singleton IS TRUE;
\gset
\if :{?baseline_generation_id}
\else
  \echo 'BLOCKED: shared draft control row is missing.'
  \quit 3
\endif

BEGIN;
SET LOCAL statement_timeout = '15s';
SET LOCAL lock_timeout = '5s';

-- Resolve the real local synthetic product and the local Administrator display
-- name before switching to the authenticated role used by the application RPCs.
SELECT set_config(
  'test.shared_positive_product_description',
  coalesce(min(btrim(descricao)), ''),
  true
)
FROM public.products
WHERE upper(btrim(referencia)) = 'TEST-CUTOVER-001';

SELECT set_config(
  'test.shared_positive_actor_name',
  coalesce(min(btrim(name)), ''),
  true
)
FROM public.profiles
WHERE id = :'admin_id'::uuid;

DO $preflight$
DECLARE
  v_product_count bigint;
  v_actor_name text := current_setting('test.shared_positive_actor_name', true);
  v_product_description text := current_setting('test.shared_positive_product_description', true);
BEGIN
  SELECT count(*) INTO v_product_count
  FROM public.products
  WHERE upper(btrim(referencia)) = 'TEST-CUTOVER-001'
    AND nullif(btrim(descricao), '') IS NOT NULL;

  IF v_product_count <> 1 OR coalesce(btrim(v_product_description), '') = '' THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_ABORT_SYNTHETIC_PRODUCT_NOT_UNIQUE';
  END IF;
  IF coalesce(btrim(v_actor_name), '') = '' THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_ABORT_ADMIN_PROFILE_NAME_MISSING';
  END IF;

  -- Module 1 is used only when the entire E1 module is empty in all three
  -- business tables. If an explicit E1 layout exists, module 1 must be active.
  IF EXISTS (SELECT 1 FROM public.slots s WHERE s.estoque = '1' AND s.modulo = '1')
     OR EXISTS (SELECT 1 FROM public.history h WHERE h.estoque = '1' AND h.modulo = '1')
     OR EXISTS (SELECT 1 FROM public.divergencias d WHERE d.estoque = '1' AND d.modulo = '1') THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_ABORT_E1_MODULE_1_NOT_EMPTY';
  END IF;

  IF EXISTS (SELECT 1 FROM public.warehouse_layout WHERE estoque = '1')
     AND NOT EXISTS (
       SELECT 1 FROM public.warehouse_layout
       WHERE estoque = '1' AND btrim(modulo) = '1' AND ativo IS TRUE
     ) THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_ABORT_E1_MODULE_1_NOT_ACTIVE';
  END IF;

  IF EXISTS (SELECT 1 FROM public.slots WHERE id = '1-1-TEST-CUTOVER-001')
     OR EXISTS (SELECT 1 FROM public.history WHERE id = 'MOV-ROW-SHARED-POSITIVE-SMOKE-001-SYNTH')
     OR EXISTS (SELECT 1 FROM public.lancamento_batch_runs
                WHERE batch_id = 'b7a10000-0000-4000-8000-000000000001'::uuid)
     OR EXISTS (SELECT 1 FROM public.lancamento_draft_archive_lines
                WHERE line_id = 'ROW-SHARED-POSITIVE-SMOKE-001') THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_ABORT_TEST_IDENTIFIERS_ALREADY_EXIST';
  END IF;

  RAISE NOTICE 'PASS_POSITIVE_SMOKE_PREFLIGHT|product=TEST-CUTOVER-001|module=1|module_empty=true|module_active=true';
END;
$preflight$;

SET LOCAL ROLE authenticated;
SELECT set_config('request.jwt.claim.sub', :'admin_id', true);
SELECT set_config(
  'request.jwt.claims',
  jsonb_build_object('sub', :'admin_id', 'role', 'authenticated')::text,
  true
);

DO $positive_smoke$
DECLARE
  v_sku constant text := 'TEST-CUTOVER-001';
  v_module constant text := '1';
  v_position constant text := '';
  v_line_id constant text := 'ROW-SHARED-POSITIVE-SMOKE-001';
  v_slot_id constant text := '1-1-TEST-CUTOVER-001';
  v_history_id constant text := 'MOV-ROW-SHARED-POSITIVE-SMOKE-001-SYNTH';
  v_batch_id constant uuid := 'b7a10000-0000-4000-8000-000000000001'::uuid;
  v_product_description text := current_setting('test.shared_positive_product_description');
  v_actor_name text := current_setting('test.shared_positive_actor_name');
  v_date text := to_char(current_date, 'YYYY-MM-DD');
  v_hour constant text := '12:00';
  v_initial_snapshot jsonb;
  v_upsert_result jsonb;
  v_snapshot jsonb;
  v_row_data jsonb;
  v_slot_payload jsonb;
  v_history_payload jsonb;
  v_process_result jsonb;
  v_retry_result jsonb;
  v_batch_result jsonb;
  v_final_snapshot jsonb;
  v_stock_result jsonb;
  v_actual_slot jsonb;
  v_generation_id uuid;
  v_initial_revision bigint;
  v_next_generation_id uuid;
  v_slot_count bigint;
  v_history_count bigint;
  v_divergence_count bigint;
BEGIN
  -- The shared draft is global. Never consume or archive another user's lines.
  v_initial_snapshot := public.get_shared_lancamento_draft();
  IF coalesce((v_initial_snapshot->>'success')::boolean, false) IS NOT TRUE
     OR jsonb_typeof(v_initial_snapshot->'lines') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_INITIAL_DRAFT_READ_FAILED: %', v_initial_snapshot;
  END IF;
  IF jsonb_array_length(v_initial_snapshot->'lines') <> 0 THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_ABORT_SHARED_DRAFT_NOT_EMPTY';
  END IF;

  v_generation_id := (v_initial_snapshot->>'generation_id')::uuid;
  v_initial_revision := (v_initial_snapshot->>'revision')::bigint;

  -- This is the same row shape used by the React launch draft. Quantity is kept
  -- as text in row_data, as it is in the editable LancamentoRow form.
  v_row_data := jsonb_build_object(
    'id', v_line_id,
    'data', v_date,
    'estoque', '1',
    'modulo', v_module,
    'posicao', v_position,
    'referencia', v_sku,
    'quantidade', '1',
    'tipo', 'Entrada',
    'dataChacote', '',
    'hora', v_hour,
    'responsavel', v_actor_name,
    'galpao', '3',
    'restricao', 'nenhuma',
    'observacao', 'TESTE SINTETICO TRANSACIONAL - NAO E ESTOQUE REAL'
  );

  v_upsert_result := public.upsert_shared_lancamento_draft_lines(
    v_generation_id,
    jsonb_build_array(jsonb_build_object('line_id', v_line_id, 'row_data', v_row_data))
  );
  IF coalesce((v_upsert_result->>'success')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_DRAFT_UPSERT_FAILED: %', v_upsert_result;
  END IF;

  v_snapshot := public.get_shared_lancamento_draft();
  IF coalesce((v_snapshot->>'success')::boolean, false) IS NOT TRUE
     OR (v_snapshot->>'generation_id')::uuid IS DISTINCT FROM v_generation_id
     OR jsonb_array_length(coalesce(v_snapshot->'lines', '[]'::jsonb)) <> 1
     OR v_snapshot->'lines'->0->>'line_id' IS DISTINCT FROM v_line_id
     OR v_snapshot->'lines'->0->'row_data' IS DISTINCT FROM v_row_data THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_DRAFT_SNAPSHOT_INVALID: %', v_snapshot;
  END IF;
  v_initial_revision := (v_snapshot->>'revision')::bigint;

  -- This is the exact canonical E1 post-state produced by
  -- processLancamentosInSequence for a new SKU entry in an empty module.
  v_slot_payload := jsonb_build_object(
    'id', v_slot_id,
    'estoque', '1',
    'modulo', v_module,
    'posicao', v_position,
    'referencia', v_sku,
    'descricao', v_product_description,
    'saldo', 1,
    'dataChacote', '',
    'ultimaData', v_date,
    'ultimaHora', v_hour,
    'ultimoResponsavel', v_actor_name,
    'galpao', '3',
    'restricao', 'nenhuma',
    'observacao', 'TESTE SINTETICO TRANSACIONAL - NAO E ESTOQUE REAL'
  );

  -- Mirror the HistoricoMov payload and slot link created for this Entrada.
  v_history_payload := jsonb_build_object(
    'id', v_history_id,
    'dataLancamento', v_date,
    'quemLancou', v_actor_name,
    'data', v_date,
    'estoque', '1',
    'modulo', v_module,
    'posicao', v_position,
    'referencia', v_sku,
    'quantidade', 1,
    'tipo', 'Entrada',
    'dataChacote', '',
    'hora', v_hour,
    'responsavel', v_actor_name,
    'galpao', '3',
    'observacao', 'TESTE SINTETICO TRANSACIONAL - NAO E ESTOQUE REAL',
    'slot_id', v_slot_id,
    'restricao', 'nenhuma'
  );

  v_process_result := public.process_shared_lancamento_draft_batch_atomic(
    v_batch_id,
    v_generation_id,
    v_initial_revision,
    v_snapshot->'lines',
    jsonb_build_object(
      'processed_count', 1,
      'divergence_count', 0,
      'source', 'shared_lancamento_positive_functional_smoke'
    ),
    '[]'::jsonb,
    jsonb_build_array(v_slot_payload),
    '[]'::jsonb,
    '[]'::jsonb,
    jsonb_build_array(v_history_payload),
    ARRAY[]::text[]
  );

  IF coalesce((v_process_result->>'success')::boolean, false) IS NOT TRUE
     OR coalesce((v_process_result->>'already_processed')::boolean, false) IS TRUE
     OR coalesce((v_process_result->>'archived_count')::bigint, -1) <> 1 THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_BATCH_PROCESS_FAILED: %', v_process_result;
  END IF;

  v_stock_result := v_process_result->'stock_result';
  IF coalesce((v_stock_result->>'success')::boolean, false) IS NOT TRUE
     OR coalesce((v_stock_result->>'slots_written')::bigint, -1) <> 1
     OR coalesce((v_stock_result->>'history_written')::bigint, -1) <> 1
     OR coalesce((v_stock_result->>'divergencias_written')::bigint, -1) <> 0
     OR coalesce((v_stock_result->>'scopes_locked')::bigint, 0) <> 1 THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_TYPED_LAUNCH_WRITER_RESULT_INVALID: %', v_stock_result;
  END IF;

  SELECT to_jsonb(s) INTO v_actual_slot
  FROM public.slots AS s
  WHERE s.id = v_slot_id;
  IF v_actual_slot IS DISTINCT FROM v_slot_payload THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_SLOT_POST_STATE_MISMATCH|expected=%|actual=%', v_slot_payload, v_actual_slot;
  END IF;

  SELECT count(*) INTO v_slot_count
  FROM public.slots AS s
  WHERE s.estoque = '1' AND s.modulo = v_module;
  SELECT count(*) INTO v_history_count
  FROM public.history AS h
  WHERE h.estoque = '1' AND h.modulo = v_module;
  SELECT count(*) INTO v_divergence_count
  FROM public.divergencias AS d
  WHERE d.estoque = '1' AND d.modulo = v_module;

  IF v_slot_count <> 1 OR v_history_count <> 1 OR v_divergence_count <> 0 THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_BUSINESS_COUNTS_INVALID|slots=%|history=%|divergences=%',
      v_slot_count, v_history_count, v_divergence_count;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.history AS h
    WHERE h.id = v_history_id
      AND h."dataLancamento" = v_date
      AND h."quemLancou" = v_actor_name
      AND h.data = v_date
      AND h.estoque = '1'
      AND h.modulo = v_module
      AND coalesce(h.posicao, '') = ''
      AND h.referencia = v_sku
      AND h.quantidade = 1
      AND h.tipo = 'Entrada'
      AND h.hora = v_hour
      AND h.responsavel = v_actor_name
      AND h.slot_id = v_slot_id
      AND h.restricao = 'nenhuma'
  ) THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_HISTORY_EVENT_MISSING_OR_INVALID';
  END IF;

  -- Retry with the exact same batch/generation/revision must return the prior
  -- result without invoking a second stock write or duplicating its history.
  v_retry_result := public.process_shared_lancamento_draft_batch_atomic(
    v_batch_id,
    v_generation_id,
    v_initial_revision,
    v_snapshot->'lines',
    jsonb_build_object(
      'processed_count', 1,
      'divergence_count', 0,
      'source', 'shared_lancamento_positive_functional_smoke'
    ),
    '[]'::jsonb,
    jsonb_build_array(v_slot_payload),
    '[]'::jsonb,
    '[]'::jsonb,
    jsonb_build_array(v_history_payload),
    ARRAY[]::text[]
  );
  IF coalesce((v_retry_result->>'success')::boolean, false) IS NOT TRUE
     OR coalesce((v_retry_result->>'already_processed')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_IDEMPOTENCY_RETRY_FAILED: %', v_retry_result;
  END IF;

  SELECT count(*) INTO v_slot_count
  FROM public.slots AS s
  WHERE s.estoque = '1' AND s.modulo = v_module;
  SELECT count(*) INTO v_history_count
  FROM public.history AS h
  WHERE h.estoque = '1' AND h.modulo = v_module;
  SELECT count(*) INTO v_divergence_count
  FROM public.divergencias AS d
  WHERE d.estoque = '1' AND d.modulo = v_module;
  -- Business-table snapshots are readable by the authenticated application role.
  -- Internal batch/archive tables are intentionally not directly readable by
  -- authenticated; their assertions run after RESET ROLE in $archive_verify$.
  IF v_slot_count <> 1 OR v_history_count <> 1 OR v_divergence_count <> 0 THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_IDEMPOTENCY_CHANGED_BUSINESS_STATE|slots=%|history=%|divergences=%',
      v_slot_count, v_history_count, v_divergence_count;
  END IF;

  v_batch_result := public.get_shared_lancamento_batch_result(v_batch_id);
  IF coalesce((v_batch_result->>'success')::boolean, false) IS NOT TRUE
     OR v_batch_result->>'batch_id' IS DISTINCT FROM v_batch_id::text
     OR coalesce((v_batch_result->>'already_processed')::boolean, false) IS NOT TRUE THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_BATCH_RESULT_LOOKUP_FAILED: %', v_batch_result;
  END IF;

  v_final_snapshot := public.get_shared_lancamento_draft();
  IF coalesce((v_final_snapshot->>'success')::boolean, false) IS NOT TRUE
     OR (v_final_snapshot->>'generation_id')::uuid IS NOT DISTINCT FROM v_generation_id
     OR coalesce((v_final_snapshot->>'revision')::bigint, -1) <> 0
     OR jsonb_array_length(coalesce(v_final_snapshot->'lines', '[]'::jsonb)) <> 0 THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_DRAFT_FINAL_STATE_INVALID: %', v_final_snapshot;
  END IF;
  v_next_generation_id := (v_final_snapshot->>'generation_id')::uuid;

  RAISE NOTICE 'PASS_SHARED_BATCH_POSITIVE_ENTRY|sku=%|module=%|quantity=1|saldo_final=1', v_sku, v_module;
  RAISE NOTICE 'PASS_TYPED_LAUNCH_WRITER|scopes_locked=%|slots_written=1|history_written=1|divergencias_written=0', v_stock_result->>'scopes_locked';
  RAISE NOTICE 'PASS_HISTORY_AUDIT|movement=%|slot_id=%|type=Entrada|quantity=1', v_history_id, v_slot_id;
  RAISE NOTICE 'PASS_DRAFT_FINALIZED|archived_count=1|active_lines=0|revision=0|next_generation=%', v_next_generation_id;
  RAISE NOTICE 'PASS_POSITIVE_STOCK_SNAPSHOT|slots=1|history=1|divergencias=0';
END;
$positive_smoke$;

RESET ROLE;

DO $archive_verify$
DECLARE
  v_batch_id constant uuid := 'b7a10000-0000-4000-8000-000000000001'::uuid;
  v_line_id constant text := 'ROW-SHARED-POSITIVE-SMOKE-001';
  v_archive_count bigint;
  v_processed_count bigint;
  v_batch_count bigint;
BEGIN
  SELECT count(*), count(*) FILTER (WHERE a.disposition = 'processed')
    INTO v_archive_count, v_processed_count
  FROM public.lancamento_draft_archive_lines AS a
  WHERE a.batch_id = v_batch_id AND a.line_id = v_line_id;
  SELECT count(*) INTO v_batch_count
  FROM public.lancamento_batch_runs AS r
  WHERE r.batch_id = v_batch_id;

  IF v_archive_count <> 1 OR v_processed_count <> 1 OR v_batch_count <> 1 THEN
    RAISE EXCEPTION 'POSITIVE_SMOKE_IDEMPOTENCY_CHANGED_INTERNAL_STATE|archive=%|processed=%|batch=%',
      v_archive_count, v_processed_count, v_batch_count;
  END IF;
  RAISE NOTICE 'PASS_SHARED_BATCH_IDEMPOTENCY|batch_records=1|archive_processed=1|no_duplicate_writes=true';
  RAISE NOTICE 'PASS_POSITIVE_DRAFT_ARCHIVED_AS_PROCESSED|lines=1|batch_records=1';
END;
$archive_verify$;

ROLLBACK;

-- Prove the transaction left no synthetic business, batch, archive or draft row,
-- and that the shared generation/revision returned to its exact prior state.
SELECT CASE WHEN
  NOT EXISTS (SELECT 1 FROM public.slots WHERE id = '1-1-TEST-CUTOVER-001')
  AND NOT EXISTS (SELECT 1 FROM public.history WHERE id = 'MOV-ROW-SHARED-POSITIVE-SMOKE-001-SYNTH')
  AND NOT EXISTS (SELECT 1 FROM public.divergencias WHERE estoque = '1' AND modulo = '1')
  AND NOT EXISTS (SELECT 1 FROM public.lancamento_batch_runs WHERE batch_id = 'b7a10000-0000-4000-8000-000000000001'::uuid)
  AND NOT EXISTS (SELECT 1 FROM public.lancamento_draft_archive_lines WHERE line_id = 'ROW-SHARED-POSITIVE-SMOKE-001')
  AND NOT EXISTS (SELECT 1 FROM public.lancamento_draft_lines WHERE line_id = 'ROW-SHARED-POSITIVE-SMOKE-001')
  AND EXISTS (
    SELECT 1 FROM public.lancamento_draft_control
    WHERE singleton IS TRUE
      AND generation_id = :'baseline_generation_id'::uuid
      AND revision = :'baseline_revision'::bigint
  )
THEN 'PASS_SHARED_BATCH_POSITIVE_SMOKE_ROLLED_BACK_NO_PERSISTENT_DATA'
ELSE 'FAIL_SHARED_BATCH_POSITIVE_SMOKE_ROLLBACK_VERIFICATION'
END AS result;
